def comps(g,val=0):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==val and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); c=[]
                touch=False
                while st:
                    y,x=st.pop(); c.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if not(0<=ny<h and 0<=nx<w): touch=True; continue
                        if g[ny][nx]==val and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx))
                out.append((c,touch))
    return out
